<script lang="ts">
	import { uiText as t } from './i18n';
	export type Extras={work_days:number|null;paid_days:number|null;include_thr:boolean;months_worked:number|null;tax_category:string|null;adjustments:{label:string;kind:string;amount:number;taxable:boolean}[]};
	let {categories=[],value=$bindable<Extras>({work_days:null,paid_days:null,include_thr:false,months_worked:null,tax_category:null,adjustments:[]})}:{value:Extras;categories?:string[]}=$props();
</script>
<details class="extras"><summary>{t('Prorata, THR, dan penyesuaian')}</summary><div class="fields"><label>{t('Hari kerja (opsional)')}<input type="number" value={value.work_days??''} oninput={event=>{value.work_days=event.currentTarget.value?Number(event.currentTarget.value):null;if(value.work_days===null)value.paid_days=null;}} min="1" max="366" step="1"/></label><label>{t('Hari dibayar')}<input type="number" bind:value={value.paid_days} min="0" max={value.work_days??366} step="1" required={value.work_days!==null} disabled={value.work_days===null}/></label><label>{t('Kategori pajak (opsional)')}<select value={value.tax_category??''} onchange={event=>value.tax_category=event.currentTarget.value||null} required={categories.length>0}><option value="">{t('Pilih kategori')}</option>{#each categories as category}<option value={category}>{category}</option>{/each}</select></label><label class="check"><input type="checkbox" bind:checked={value.include_thr}/>{t('Sertakan THR')}</label>{#if value.include_thr}<label>{t('Masa kerja untuk THR (bulan)')}<input type="number" bind:value={value.months_worked} min="0" max="12" step="1" required/></label>{/if}</div><p>{t('Nominal tambahan dan potongan memakai rupiah penuh. Perhitungan mengikuti aturan perusahaan, bukan tarif pajak bawaan.')}</p>{#each value.adjustments as adjustment,index}<div class="adjustment"><label>{t('Nama')}<input bind:value={adjustment.label} maxlength="100" required/></label><label>{t('Jenis')}<select bind:value={adjustment.kind}><option value="earning">{t('Penghasilan')}</option><option value="deduction">{t('Potongan')}</option></select></label><label>{t('Nominal (Rp)')}<input type="number" bind:value={adjustment.amount} min="0" max="999999999" step="1" required/></label>{#if adjustment.kind==='earning'}<label class="check"><input type="checkbox" bind:checked={adjustment.taxable}/>{t('Termasuk penghasilan kena pajak')}</label>{/if}<button type="button" class="quiet" onclick={()=>value.adjustments=value.adjustments.filter((_,i)=>i!==index)}>{t('Hapus')}</button></div>{/each}<button type="button" class="quiet" disabled={value.adjustments.length>=30} onclick={()=>value.adjustments=[...value.adjustments,{label:'',kind:'earning',amount:0,taxable:true}]}>{t('Tambah penyesuaian')}</button></details>
<style>.extras{font-size:12px}summary{font-weight:700;cursor:pointer}.fields,.adjustment{display:grid;gap:8px;margin-top:12px}p{color:var(--muted)}.check{display:flex;align-items:center;gap:8px}.check input{width:auto}</style>
